   class SystemPromptBuilder:
       BASE_INSTRUCTIONS = """
       You are a helpful AI assistant with access to specialized skills.

       ## Available Skills
       When a user's request matches a skill, use the load_skill tool to get full instructions.

       | Name | Description |
       |------|-------------|
       {skill_catalog}

       ## Important Guidelines
       - Only use skills when relevant to the user's request
       - Do not speculate about skill capabilities - load them first
       - ...
       """

       def build(self, skills: list[dict], tools: list[dict]) -> str:
           catalog = "\n".join(
               f"| {s['name']} | {s['description']} |"
               for s in skills
           )
           return self.BASE_INSTRUCTIONS.format(
               skill_catalog=catalog,
               tool_descriptions=self._format_tools(tools)
           )
