2. **Execution Handler**:
   ```python
   async def execute_save_skill(
       name: str,
       description: str,
       instructions: str,
       user_id: str,
       skills_service: SkillsService,
       enabled: bool = True
   ) -> dict:
       try:
           # Validate via Pydantic model
           skill_data = SkillCreate(
               name=name,
               description=description,
               instructions=instructions,
               enabled=enabled
           )

           # Create skill
           created = await skills_service.create_skill(user_id, skill_data)

           return {
               "success": True,
               "skill_id": created.id,
               "name": created.name,
               "message": f"Skill '{name}' created successfully"
           }
       except ValidationError as e:
           return {"error": "Validation failed", "details": e.errors()}
       except Exception as e:
           # Handle duplicate name, etc.
           return {"error": str(e)}
   ```

