       if not valid:
           yield {"event": "error", "data": {"message": error}}
           return

       # Get or create sandbox session
       session = await sandbox_manager.get_or_create_session(thread_id, user_id)

       # Record execution start
       execution = await create_execution_record(thread_id, user_id, code)

       yield {"event": "start", "data": {"execution_id": execution['id']}}

       # Install libraries if needed
