       # Create ZIP in memory
       buffer = io.BytesIO()
       with zipfile.ZipFile(buffer, 'w', zipfile.ZIP_DEFLATED) as zf:
           # Add SKILL.md
           skill_md = SkillStandard.generate_skill_md(skill)
           zf.writestr('SKILL.md', skill_md)

           # Add categorized files
           for file in files:
               content = await file_service.download_file(file['id'])
               category = SkillStandard.categorize_file(file['filename'], file['mime_type'])
               zf.writestr(f"{category}/{file['filename']}", content)

       buffer.seek(0)
       return StreamingResponse(
           buffer,
           media_type='application/zip',
           headers={'Content-Disposition': f'attachment; filename="{skill["name"]}.zip"'}
