   @router.post("/import")
   async def import_skills(
       file: UploadFile,
       user: User = Depends(get_current_user)
   ):
       if file.size > 50 * 1024 * 1024:  # 50 MB limit
           raise HTTPException(400, "File too large")

       content = await file.read()
       buffer = io.BytesIO(content)

       results = []
       with zipfile.ZipFile(buffer, 'r') as zf:
           # Check for single SKILL.md or multiple skill directories
           if 'SKILL.md' in zf.namelist():
               # Single skill import
               result = await import_single_skill(zf, user.id)
               results.append(result)
           else:
               # Bulk import - each subdirectory is a skill
               for name in zf.namelist():
                   if name.endswith('/SKILL.md'):
                       skill_dir = name.rsplit('/', 1)[0]
                       result = await import_skill_from_dir(zf, skill_dir, user.id)
                       results.append(result)

       return {"imported": results}

   async def import_single_skill(zf: zipfile.ZipFile, user_id: str) -> dict:
       # Parse SKILL.md
       skill_md = zf.read('SKILL.md').decode('utf-8')
       skill_data = SkillStandard.parse_skill_md(skill_md)

       # Check for name conflicts
       existing = await skills_service.get_skill_by_name(skill_data['name'], user_id)
       if existing:
           skill_data['name'] = f"{skill_data['name']}-imported-{int(time.time())}"

       # Create skill
       skill = await skills_service.create_skill(user_id, skill_data)

       # Import attached files
       for name in zf.namelist():
           if name != 'SKILL.md' and not name.endswith('/'):
               content = zf.read(name)
               filename = Path(name).name
               await file_service.upload_file_from_bytes(
                   skill['id'], user_id, filename, content
               )

       return {"name": skill['name'], "id": skill['id'], "status": "success"}
